// M03 file ingestion against the real engine (DuckDB v1.5.4): known-answer CSV/Parquet fixtures
// (tests/fixtures/import, generated by scripts/fixtures/make_import_fixtures.py with expected
// values written independently of DuckDB), transactional cleanup, admission, naming,
// cancellation, open-transaction refusal and recovery during import.
import { expect, test, type Page } from '@playwright/test';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { captureRequests, HARNESS } from './helpers';

const FIX = path.resolve('tests/fixtures/import');
const EXPECTED = JSON.parse(readFileSync(path.join(FIX, 'expected.json'), 'utf8')) as Record<string, { columns: string[]; rows: (string | null)[][]; types?: string[] }>;
const b64 = (name: string) => readFileSync(path.join(FIX, name)).toString('base64');
const text64 = (s: string) => Buffer.from(s, 'utf8').toString('base64');

type Src = { name: string; data: string; requestedName?: string };
type Outcome = { status: string; detail?: string; relation?: string };
const fx = (name: string, requestedName?: string): Src => ({ name, data: b64(name), ...(requestedName ? { requestedName } : {}) });

async function open(page: Page, imports: Record<string, number> = {}, bounds: Record<string, number> = {}) {
  await page.goto(HARNESS);
  await page.waitForFunction(() => window.__qvHarness?.datasets !== undefined);
  await page.evaluate(([i, b]) => window.__qvHarness!.datasets!.setup(i, b), [imports, bounds] as const);
}

/** Imports the files in one batch and waits for every outcome. */
function importAll(page: Page, files: Src[]): Promise<Outcome[]> {
  return page.evaluate(async (files) => {
    const D = window.__qvHarness!.datasets!;
    const { handles } = D.current().datasets.importer.import(files.map((f) => ({ file: D.file(f.name, f.data), ...(f.requestedName ? { requestedName: f.requestedName } : {}) })));
    const out = [];
    for (const h of handles) {
      const r = await h.result;
      const t = r.terminal as { status: string; message?: string; reason?: string };
      out.push({ status: t.status, detail: t.message ?? t.reason, relation: r.value?.relation });
    }
    return out;
  }, files);
}

/** The engine-side evidence that nothing was left behind. */
function leftovers(page: Page) {
  return page.evaluate(async () => {
    const D = window.__qvHarness!.datasets!;
    const probes = [];
    for (const p of D.registrationLog) probes.push(await D.readable(p));
    return { tables: await D.tables(), registered: [...D.registeredFiles], anyPathReadable: probes.some(Boolean), noOpenTransaction: await D.noOpenTransaction() };
  });
}

const dump = (page: Page, relation: string) => page.evaluate((r) => window.__qvHarness!.datasets!.dump(r), relation);

test.describe('file ingestion (M03)', () => {
  test('CSV known answers: NULL vs empty string, quoted commas, escaped quotes, newlines, int64 edges, header-only', async ({ page }) => {
    await open(page);
    const r = await importAll(page, [fx('people.csv'), fx('bigints.csv'), fx('header_only.csv')]);
    expect(r).toEqual([{ status: 'ok', relation: 'people' }, { status: 'ok', relation: 'bigints' }, { status: 'ok', relation: 'header_only' }]);
    for (const [rel, file] of [['people', 'people.csv'], ['bigints', 'bigints.csv'], ['header_only', 'header_only.csv']] as const) {
      const d = await dump(page, rel);
      expect(d.columns).toEqual(EXPECTED[file]!.columns);
      expect(d.rows).toEqual(EXPECTED[file]!.rows);
    }
    expect((await dump(page, 'people')).types).toEqual(['BIGINT', 'VARCHAR', 'VARCHAR', 'VARCHAR']);
    expect((await dump(page, 'bigints')).types).toEqual(['BIGINT']);
    expect((await dump(page, 'header_only')).types).toEqual(['VARCHAR', 'VARCHAR']);
    expect(await leftovers(page)).toMatchObject({ registered: [], anyPathReadable: false, noOpenTransaction: true });
  });

  test('CSV never rounds: integers beyond int64 and decimals stay exact text (no DOUBLE candidate)', async ({ page }) => {
    await open(page);
    const r = await importAll(page, [{ name: 'wide.csv', data: text64('big,dec,flag,day\n18446744073709551616,12345678901234567.89,true,2024-02-29\n1,0.10,false,2024-03-01\n') }]);
    expect(r[0]?.status).toBe('ok');
    const d = await dump(page, 'wide');
    expect(d.types).toEqual(['VARCHAR', 'VARCHAR', 'BOOLEAN', 'DATE']);
    expect(d.rows).toEqual([['18446744073709551616', '12345678901234567.89', 'true', '2024-02-29'], ['1', '0.10', 'false', '2024-03-01']]);
  });

  test('Parquet known answers: types, exact DECIMAL and BIGINT, NULL vs empty string', async ({ page }) => {
    await open(page);
    expect(await importAll(page, [fx('people.parquet')])).toEqual([{ status: 'ok', relation: 'people' }]);
    const d = await dump(page, 'people');
    expect(d).toMatchObject({ columns: EXPECTED['people.parquet']!.columns, types: EXPECTED['people.parquet']!.types, rows: EXPECTED['people.parquet']!.rows });
  });

  test('malformed, ragged and non-Parquet files fail and leave no table, registered file or open transaction', async ({ page }) => {
    await open(page);
    const r = await importAll(page, [fx('malformed_quote.csv'), fx('ragged.csv'), fx('not_parquet.parquet')]);
    expect(r.map((x) => x.status)).toEqual(['error', 'error', 'error']);
    expect(r[2]?.detail).toMatch(/magic bytes/i);
    expect(await leftovers(page)).toEqual({ tables: [], registered: [], anyPathReadable: false, noOpenTransaction: true });
    expect(await page.evaluate(() => window.__qvHarness!.datasets!.registrationLog.length)).toBe(3);
    // The session is still usable and the names are still free.
    expect(await importAll(page, [{ name: 'ragged.csv', data: text64('a,b\n1,2\n') }])).toEqual([{ status: 'ok', relation: 'ragged' }]);
  });

  test('admission uses actual byte sizes and the combined cap includes earlier imports; refusals never reach the engine', async ({ page }) => {
    await open(page, { maxFileBytes: 100, maxCombinedBytes: 100 });
    const r = await importAll(page, [fx('people.csv'), fx('empty.csv'), { name: 'notes.txt', data: text64('a\n') }, fx('bigints.csv')]);
    expect(r.map((x) => x.status)).toEqual(['refused', 'refused', 'refused', 'ok']); // 105 B > 100 B; 0 B; .txt; 60 B
    expect(r[0]?.detail).toMatch(/per file/);
    const again = await importAll(page, [fx('bigints.csv')]); // 60 + 60 > 100
    expect(again[0]).toMatchObject({ status: 'refused', detail: expect.stringMatching(/combined/) });
    expect(await page.evaluate(() => window.__qvHarness!.datasets!.registrationLog.length)).toBe(1);
  });

  test('same file name twice, concurrently, gives separate tables (Phase 3 registration defect regression)', async ({ page }) => {
    await open(page);
    const [a, b] = await Promise.all([
      importAll(page, [fx('people.csv'), fx('people.csv')]),
      importAll(page, [{ name: 'people.csv', data: text64('id\n7\n') }]),
    ]);
    expect([...(a ?? []), ...(b ?? [])].map((x) => x.relation).sort()).toEqual(['people', 'people_2', 'people_3']);
    const counts = await page.evaluate(async () => {
      const D = window.__qvHarness!.datasets!;
      const s = D.current().session;
      const out: Record<string, string | null | undefined> = {};
      for (const t of ['people', 'people_2', 'people_3']) out[t] = (await D.sql(s, `SELECT count(*)::VARCHAR FROM ${t}`)).rows?.[0]?.[0];
      return out;
    });
    expect(Object.values(counts).sort()).toEqual(['1', '4', '4']);
    // Every distinct import used its own virtual path.
    expect(await page.evaluate(() => new Set(window.__qvHarness!.datasets!.registrationLog).size)).toBe(3);
  });

  test('catalog collisions and reserved words: never overwrite, never silently rename a requested name', async ({ page }) => {
    await open(page);
    await page.evaluate(async () => {
      const D = window.__qvHarness!.datasets!;
      await D.sql(D.current().session, 'CREATE TABLE sales (a INTEGER)');
    });
    const r = await importAll(page, [{ name: 'Sales.csv', data: text64('x\n1\n') }, { name: 'x.csv', data: text64('x\n1\n'), requestedName: 'sales' }, { name: 'select.csv', data: text64('x\n1\n') }, { name: 'y.csv', data: text64('x\n1\n'), requestedName: 'select' }, { name: 'z.csv', data: text64('x\n1\n'), requestedName: 'a"; DROP TABLE sales; --' }]);
    expect(r.map((x) => [x.status, x.relation])).toEqual([['ok', 'sales_2'], ['refused', undefined], ['ok', 'select_data'], ['refused', undefined], ['refused', undefined]]);
    expect(r[1]?.detail).toMatch(/already exists/);
    expect(await dump(page, 'sales')).toMatchObject({ columns: ['a'], types: ['INTEGER'], rows: [] });
  });

  test('a queued import cancelled before it starts does no engine work', async ({ page }) => {
    await open(page);
    const r = await page.evaluate(async (data) => {
      const D = window.__qvHarness!.datasets!;
      D.faults.hold = /^CREATE TABLE/;
      const imp = D.current().datasets.importer;
      const first = imp.import([{ file: D.file('one.csv', data) }]).handles[0]!;
      const second = imp.import([{ file: D.file('two.csv', data) }]).handles[0]!;
      await D.waitFor(() => D.held.length === 1);
      second.cancel();
      const s2 = (await second.result).terminal;
      D.faults.hold = null;
      D.held[0]!.release();
      const s1 = (await first.result).terminal;
      return { s1: s1.status, s2, log: D.registrationLog.length };
    }, b64('people.csv'));
    expect(r).toEqual({ s1: 'ok', s2: { status: 'cancelled', by: 'user', stop: 'cooperative' }, log: 1 });
    expect(await leftovers(page)).toMatchObject({ tables: ['one'], registered: [], noOpenTransaction: true });
  });

  test('an active import cancelled during CREATE rolls back and unregisters its file', async ({ page }) => {
    await open(page);
    const r = await page.evaluate(async (data) => {
      const D = window.__qvHarness!.datasets!;
      D.faults.hold = /^CREATE TABLE/;
      const { handles, progress } = D.current().datasets.importer.import([{ file: D.file('slow.csv', data) }]);
      await D.waitFor(() => D.held.length === 1);
      const during = { registered: D.registeredFiles.size, stage: progress.getSnapshot()[0]?.stage };
      handles[0]!.cancel();
      const t = (await handles[0]!.result).terminal;
      D.faults.hold = null;
      return { during, t, stage: progress.getSnapshot()[0]?.stage, generation: D.current().session.generation };
    }, b64('people.csv'));
    expect(r).toMatchObject({ during: { registered: 1, stage: 'reading' }, t: { status: 'cancelled', by: 'user', stop: 'cooperative' }, stage: 'cancelled', generation: 1 });
    expect(await leftovers(page)).toEqual({ tables: [], registered: [], anyPathReadable: false, noOpenTransaction: true });
    expect(await importAll(page, [fx('people.csv')])).toEqual([{ status: 'ok', relation: 'people' }]);
  });

  test('an import that exceeds its deadline is stopped and cleaned up', async ({ page }) => {
    await open(page, {}, { importMs: 300 });
    const r = await page.evaluate(async (data) => {
      const D = window.__qvHarness!.datasets!;
      D.faults.hold = /^CREATE TABLE/;
      const h = D.current().datasets.importer.import([{ file: D.file('slow.csv', data) }]).handles[0]!;
      const t = (await h.result).terminal;
      D.faults.hold = null;
      return t;
    }, b64('people.csv'));
    expect(r).toMatchObject({ status: 'cancelled', by: 'deadline' });
    expect(await leftovers(page)).toEqual({ tables: [], registered: [], anyPathReadable: false, noOpenTransaction: true });
  });

  test('control: the leftover probe detects a registered file and a dropped one', async ({ page }) => {
    await open(page);
    const r = await page.evaluate(async () => {
      const D = window.__qvHarness!.datasets!;
      const s = D.current().session;
      await s.submit('import', (l) => l.registerFile('/qv-local/control.csv', new File(['a\n1\n'], 'control.csv')), D.BOUNDS).result;
      const registered = await D.readable('/qv-local/control.csv');
      await s.submit('import', (l) => l.dropFile('/qv-local/control.csv'), D.BOUNDS).result;
      return { registered, dropped: await D.readable('/qv-local/control.csv') };
    });
    expect(r).toEqual({ registered: true, dropped: false });
  });

  test('an open user transaction refuses the import and is left untouched', async ({ page }) => {
    await open(page);
    const r = await page.evaluate(async (data) => {
      const D = window.__qvHarness!.datasets!;
      const s = D.current().session;
      await D.sql(s, 'BEGIN TRANSACTION');
      await D.sql(s, 'CREATE TABLE mine AS SELECT 1 AS v');
      const t = (await D.current().datasets.importer.import([{ file: D.file('t.csv', data) }]).handles[0]!.result).terminal;
      // The user's transaction is still usable: its own work is visible before COMMIT.
      const inside = (await D.sql(s, 'SELECT v::VARCHAR FROM mine')).rows;
      const commit = (await D.sql(s, 'COMMIT')).terminal.status;
      return { t, inside, commit, registered: D.registeredFiles.size };
    }, b64('people.csv'));
    expect(r).toMatchObject({ t: { status: 'refused', reason: expect.stringMatching(/transaction is open/) }, inside: [['1']], commit: 'ok', registered: 0 });
    expect((await leftovers(page)).tables).toEqual(['mine']);
  });

  test('engine recovery during an import: nothing is published and no table survives', async ({ page }) => {
    await open(page);
    const r = await page.evaluate(async (data) => {
      const D = window.__qvHarness!.datasets!;
      const { session, datasets } = D.current();
      D.faults.hold = /^CREATE TABLE/;
      const h = datasets.importer.import([{ file: D.file('lost.csv', data) }]).handles[0]!;
      await D.waitFor(() => D.held.length === 1);
      D.faults.hold = null;
      await session.restart('test: recovery during import');
      const t = (await h.result).terminal;
      await datasets.registry.reconcile();
      return { t, generation: session.generation, entries: datasets.registry.getSnapshot().map((e) => e.relation) };
    }, b64('people.csv'));
    expect(['stale', 'cancelled', 'error']).toContain(r.t.status);
    expect(r.generation).toBe(2);
    expect(r.entries).toEqual([]);
    expect(await leftovers(page)).toMatchObject({ tables: [], registered: [], noOpenTransaction: true });
  });

  test('importing, re-importing and removing make no request outside the page origin', async ({ page, context }) => {
    const requests = captureRequests(context);
    await open(page);
    const before = requests.length;
    const r = await page.evaluate(async ([csv, pq]) => {
      const D = window.__qvHarness!.datasets!;
      const { session, datasets } = D.current();
      const a = await datasets.importer.import([{ file: D.file('people.csv', csv) }, { file: D.file('people.parquet', pq) }]).handles.reduce(async (acc, h) => [...(await acc), (await h.result).terminal.status], Promise.resolve([] as string[]));
      await session.restart('test');
      const b = (await datasets.registry.reimport('people').result).terminal.status;
      const c = (await datasets.registry.remove('people').result).terminal.status;
      return [...a, b, c];
    }, [b64('people.csv'), b64('people.parquet')] as const);
    expect(r).toEqual(['ok', 'ok', 'ok', 'ok']);
    const during = requests.slice(before).map((q) => q.url());
    expect(during.filter((u) => !u.startsWith(new URL(HARNESS).origin) && !u.startsWith('blob:') && !u.startsWith('data:'))).toEqual([]);
  });

  test('a successful import advances the data epoch', async ({ page }) => {
    await open(page);
    const before = await page.evaluate(() => window.__qvHarness!.datasets!.current().session.epoch);
    await importAll(page, [fx('people.csv')]);
    const after = await page.evaluate(() => window.__qvHarness!.datasets!.current().session.epoch);
    expect(after).toBeGreaterThan(before);
  });
});
